('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--10',1,'{"question":"An artist uses recycled materials to address consumption. What relationship is the work exploring?","choices":["A requirement that all art be temporary","Material choice and environmental or social meaning","The history of oil painting only","A color-mixing rule"],"answer":1,"explanation":""}'::jsonb,'2ef7d849e60cd25aa29a048804fadc37','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--11',1,'{"question":"What is an ethical question that may arise in contemporary art?","choices":["Whether every artwork must rhyme","Whether the gallery has enough frames","How permissions, cultural ownership, and community impacts are handled","Whether the work uses a title"],"answer":2,"explanation":""}'::jsonb,'4fd79da27b6d25eaca65ed5c9fab3d4f','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--12',1,'{"question":"A work changes when viewers contribute messages. What type of participation is involved?","choices":["Linear perspective","Fresco painting","Contrapposto","Interactive or participatory engagement"],"answer":3,"explanation":""}'::jsonb,'84c4fcfd04080716953c83b082b579b6','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--13',1,'{"question":"Why can an artist''s statement help viewers?","choices":["It can provide context about questions, materials, or intentions behind the work","It fixes one required interpretation","It replaces the artwork","It proves every viewer must agree"],"answer":0,"explanation":""}'::jsonb,'9daa0ec207324655da36e80080e9ad25','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--14',1,'{"question":"What should viewers remember when reading an artist''s statement?","choices":["It is the only possible meaning","It is useful context, while visual evidence and other interpretations still matter","It replaces historical research","It must be treated as a museum label"],"answer":1,"explanation":""}'::jsonb,'9c07e8d72bf1ae8b72767b1341bc9382','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--15',1,'{"question":"A contemporary sculpture is temporary and will change outdoors. What concept may be central?","choices":["A requirement of classical proportion","A ban on audience response","Time, material change, or impermanence","A fixed permanent surface"],"answer":2,"explanation":""}'::jsonb,'8396dc4c266a74f2c002362f3606eb5a','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--16',1,'{"question":"What is a curatorial choice?","choices":["A method for carving marble","A way to calculate perspective","A kind of paint pigment","A decision about selecting and arranging works for an exhibition"],"answer":3,"explanation":""}'::jsonb,'7998eb20967dbb92363cb2919101087d','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--17',1,'{"question":"An exhibition places two works side by side. What can this arrangement do?","choices":["Encourage viewers to compare or connect the works","Guarantee they share one meaning","Remove their historical context","Make the works identical"],"answer":0,"explanation":""}'::jsonb,'2ea214f46e96ff5c81ddb4a0a50d8130','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--18',1,'{"question":"Why may contemporary art address social or political questions?","choices":["Art is required to endorse one policy","Artists can use visual practice to examine current issues and experiences","Art cannot address public life","Only written essays can discuss society"],"answer":1,"explanation":""}'::jsonb,'8a16d86692d8ce0307e24469dd5af00e','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--19',1,'{"question":"A viewer dislikes an artwork. What is a productive next step for analysis?","choices":["Stop looking immediately","Assume the artist failed","Describe the choices that shaped the response and support an interpretation with evidence","Treat personal taste as the only standard"],"answer":2,"explanation":""}'::jsonb,'9ac4fc6b5db1a9a55b97231055fa71f0','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--contemporary-art-artists:fine-arts--art-history--contemporary-art-artists--20',1,'{"question":"Which statement best describes diversity in contemporary art?","choices":["All contemporary artists share one message","Only digital works qualify","Contemporary art excludes craft","Artists work across many styles, media, communities, and purposes"],"answer":3,"explanation":""}'::jsonb,'08a2381e0fbd7b89a982624c37fcff1a','official',NULL,NULL,'Contemporary Art & Artists'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--1',1,'{"question":"Which step is a useful starting point for analyzing an unfamiliar artwork?","choices":["Describe what is visibly present before interpreting it","Guess the artist''s personality","Rank it against every other artwork","Decide whether it is expensive"],"answer":0,"explanation":""}'::jsonb,'08e94f6c6d1ea5b85bec17e6dde4cea9','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--2',1,'{"question":"Which sentence is an observation rather than an interpretation?","choices":["The figures are afraid","The image contains three figures and a red shape near the center","The red shape symbolizes anger","The artist criticizes society"],"answer":1,"explanation":""}'::jsonb,'a89b1817a372e66ef5c32edf9da68266','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--3',1,'{"question":"What does formal analysis examine?","choices":["Only the artist''s biography","The work''s sale price","Elements and principles such as line, color, shape, balance, and composition","The museum''s opening hours"],"answer":2,"explanation":""}'::jsonb,'b4ae6b61d7fda88c8f9c22a7076759d8','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--4',1,'{"question":"A viewer claims a dark background creates a feeling of isolation. What would strengthen the interpretation?","choices":["Repeat the claim more loudly","Name the frame''s material","Ask whether others agree without evidence","Point to visual evidence and explain how it supports that effect"],"answer":3,"explanation":""}'::jsonb,'302f3f077ececd4cb42d504d488cd941','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--5',1,'{"question":"What is composition?","choices":["The arrangement of visual elements within an artwork","The artwork''s shipping method","A list of gallery rules","A type of pigment"],"answer":0,"explanation":""}'::jsonb,'01cdf52fe8af66acf0d3098acd1b6565','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--6',1,'{"question":"Which principle describes how visual weight is distributed?","choices":["Tempo","Balance","Rhyme","Scale"],"answer":1,"explanation":""}'::jsonb,'61705669b7ba35fcc75b54395015ec96','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--7',1,'{"question":"How can context contribute to art analysis?","choices":["It determines one fixed meaning","It replaces looking closely","It can clarify historical, cultural, social, or material conditions around the work","It proves the artist''s private thoughts"],"answer":2,"explanation":""}'::jsonb,'a3c33f6a9f12e0097502495d06215a35','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--8',1,'{"question":"A painting uses repeated curved lines that guide the eye toward a figure. What can the viewer analyze?","choices":["The artist''s height","The gallery''s floor plan","The painting''s shipping weight","How line directs attention and contributes to the composition"],"answer":3,"explanation":""}'::jsonb,'3e970b607828ec1276a3693e78fc2a0a','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--9',1,'{"question":"What is a defensible interpretation?","choices":["A claim about meaning supported by details in the artwork and relevant context","A guess without evidence","A statement that everyone must agree","A summary of the title only"],"answer":0,"explanation":""}'::jsonb,'45f7441104f4143b3577490890739217','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--10',1,'{"question":"Why can two viewers interpret the same artwork differently?","choices":["Artworks have no visible features","They may notice different evidence or bring different experiences and contexts","Only one viewer can understand art","Interpretation is always random"],"answer":1,"explanation":""}'::jsonb,'a83b412d65b5504c3533e7efcf86ae14','official',NULL,NULL,'How to Analyze & Discuss Art'),
