('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--12',1,'{"question":"A student says, ''This is good art because I like it.'' How can the response deepen?","choices":["Repeat the opinion","Avoid describing the work","Assume taste needs no explanation","Explain which choices create the response and support the view with evidence"],"answer":3,"explanation":""}'::jsonb,'599f287420851089ce9f48e1b336709a','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--13',1,'{"question":"What is negative space?","choices":["The empty or unoccupied areas around and between forms","A dark pigment","A missing frame","A type of sculpture"],"answer":0,"explanation":""}'::jsonb,'676bcc12957f8b09870387e6de0fa307','official',NULL,NULL,'How to Analyze & Discuss Art'),
('original:fine-arts--art-history--how-to-analyze-discuss-art:fine-arts--art-history--how-to-analyze-discuss-art--14',1,'{"question":"Which statement best distinguishes subject from theme?","choices":["Subject and theme always mean the same thing","Subject is what is depicted; theme is an idea the work may explore","Theme is the material; subject is the frame","Subject is the artist''s name"],"answer":1,"explanation":""}'::jsonb,'6c3214eee4e3855154b2e564d7875793','official',NULL,NULL,'How to Analyze & Discuss Art'),
