('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--8',1,'{"question":"A performance combines breaking, house, and locking. What does this illustrate?","choices":["Dance styles cannot overlap","The performers are not dancing","Every style has the same history","A dance work can draw from multiple styles"],"answer":3,"explanation":""}'::jsonb,'3c8984e32ec3cf46226069c3239bf422','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--9',1,'{"question":"What is one useful way to identify a style in a performance?","choices":["Notice movement qualities, musical relationships, and relevant cultural context","Guess from costume alone","Use only the stage color","Assume every fast dance is hip-hop"],"answer":0,"explanation":""}'::jsonb,'827cff7890ec9a7e516a4416d148e988','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--10',1,'{"question":"Which practice is common in ballet class to develop balance and technique?","choices":["Tap shoes used for percussive sound","Exercises at a barre","Improvised street-dance battles","A circle dance at a community gathering"],"answer":1,"explanation":""}'::jsonb,'98a382e9161baa8a9c8e7d14188e620a','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--11',1,'{"question":"What should a student do when learning a dance from a culture outside their own?","choices":["Treat it as a costume theme","Assume all members of the culture dance alike","Learn its context and sources, and approach the practice respectfully","Remove its cultural context"],"answer":2,"explanation":""}'::jsonb,'328b4f78afa7205f8c47be1f10446c91','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--12',1,'{"question":"Which description best fits a folk or social dance?","choices":["A dance that can never change","A style performed only by professionals","A dance without cultural context","A dance connected to community practices and social participation"],"answer":3,"explanation":""}'::jsonb,'5df46915e31437f22f302251296605ff','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--13',1,'{"question":"A work uses ballet training but breaks from traditional ballet structure. What can be said?","choices":["It may draw on ballet technique while developing a different choreographic approach","It cannot be dance","It is necessarily a waltz","It must follow a ballet story"],"answer":0,"explanation":""}'::jsonb,'3bf66f3711b533463acc4482851fd933','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--14',1,'{"question":"What does ''fusion'' suggest when describing a dance work?","choices":["The work has no movement","The work combines movement approaches from more than one style or tradition","The work uses one fixed tradition only","The work is a written review"],"answer":1,"explanation":""}'::jsonb,'8e86d25d2fdbef8dd54f12da1f92de78','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--15',1,'{"question":"Which style commonly uses isolations of body parts and grounded rhythmic movement?","choices":["Classical ballet only","Waltz only","Many forms of hip-hop dance","Courtly minuet only"],"answer":2,"explanation":""}'::jsonb,'df98547ecfd48c761e13fa3839b7bd01','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--16',1,'{"question":"Why should students learn the historical roots of jazz and hip-hop dance?","choices":["History determines one correct costume","Context prevents learning technique","Styles have no historical roots","Context helps recognize the communities and innovations that shaped the styles"],"answer":3,"explanation":""}'::jsonb,'664a2a7afe7600f132628b65cda91489','official',NULL,NULL,'Dance Styles Overview')
