('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--18',1,'{"question":"Which statement about contemporary dance is strongest?","choices":["It has no technique","It is a broad, evolving field rather than a single uniform vocabulary","It began in ancient Greece","It uses only improvised movement"],"answer":1,"explanation":""}'::jsonb,'2588a1d485181d8abad76fefa558ed9b','official',NULL,NULL,'Dance Styles Overview'),
('original:fine-arts--dance--dance-styles-overview:fine-arts--dance--dance-styles-overview--19',1,'{"question":"What is a responsible way to compare two dance traditions?","choices":["Rank one as more advanced","Treat the traditions as interchangeable","Describe movement features and consider each tradition''s own context","Compare only costumes"],"answer":2,"explanation":""}'::jsonb,'3393e2976d300d1e5e733b55c01e70d4','official',NULL,NULL,'Dance Styles Overview'),
