('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--4',1,'{"question":"What is one respectful practice when learning a dance from a culture different from one''s own?","choices":["Treat the dance as a costume or joke","Claim the dance has no cultural meaning","Assume one video represents every community","Use reliable sources and acknowledge the tradition and its practitioners"],"answer":3,"explanation":""}'::jsonb,'1b23c288bb681aa51606951228178a9a','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--5',1,'{"question":"Why is it important to distinguish a community''s traditional practice from a commercial performance inspired by it?","choices":["The purpose, context, and cultural authority may differ","Commercial work is always more authentic","Traditional practices never change","The movement vocabulary must be unrelated"],"answer":0,"explanation":""}'::jsonb,'d10a3239a426690c4c5a2b815ae47511','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--6',1,'{"question":"A class studies a dance connected to a harvest celebration. Which question is useful?","choices":["What is the dancers'' exact height?","How does the dance relate to the community''s seasonal or ceremonial context?","Which costume is most expensive?","Can the dance be removed from its community?"],"answer":1,"explanation":""}'::jsonb,'fe0a9dadcc420c2d9c2b2c98d210cee2','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--7',1,'{"question":"What can music, costume, and movement together communicate in a cultural dance?","choices":["A single meaning that applies to all cultures","Only the choreographer''s age","Shared histories, identities, values, or occasions, depending on the tradition","A universal language with no context"],"answer":2,"explanation":""}'::jsonb,'eeff64fc7d790c9534427817b5f85952','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--8',1,'{"question":"Why should a student avoid saying that one dance represents an entire continent?","choices":["Continents have no dance","All dances come from one country","Movement cannot be compared","Regions and communities contain many distinct traditions"],"answer":3,"explanation":""}'::jsonb,'21f103a81d729458d7f5ba062e4b07d0','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--9',1,'{"question":"A dance is passed through generations but changes over time. What does this show?","choices":["Traditions can be preserved and adapted by communities","Traditions must stay identical","The dance has lost all cultural value","Change prevents historical study"],"answer":0,"explanation":""}'::jsonb,'af2dff11e61d8e3000d7e4945ba07614','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--10',1,'{"question":"When presenting a cultural dance, what information should be credited when available?","choices":["Only the costume designer","The tradition, community or practitioners, and source of the learning material","No sources are needed","A made-up origin story"],"answer":1,"explanation":""}'::jsonb,'03b6e6aa9336e587079c69ed052f62f0','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--11',1,'{"question":"Why might a dance be performed in a circle?","choices":["Every circle dance has the same origin","The shape proves the dance is ancient","The formation may support shared participation or a particular social meaning","Circles prevent audience viewing"],"answer":2,"explanation":""}'::jsonb,'3d2bb58b9e95793a88dc4ad0e3596a3e','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--12',1,'{"question":"A dance includes gestures that carry culturally specific meaning. What should a learner do?","choices":["Assign a meaning from personal preference","Remove every gesture","Assume gestures mean the same thing everywhere","Learn the meaning from knowledgeable sources rather than guessing"],"answer":3,"explanation":""}'::jsonb,'bce72c27fb84c73ea669cf8df1c7e0ad','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--13',1,'{"question":"Which statement about cultural dance is most accurate?","choices":["Dance can be artistic, social, ceremonial, communal, or some combination","Every cultural dance is a stage performance","All traditions are religious","Cultural dances have no audiences"],"answer":0,"explanation":""}'::jsonb,'e0307e2156bd44a230e26113f83f284d','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--14',1,'{"question":"Why is consent and community input important when documenting a cultural dance?","choices":["It makes the recording more colorful","It respects participants and can shape what should be recorded or shared","It proves every movement is public property","It replaces historical research"],"answer":1,"explanation":""}'::jsonb,'a21f8e9aa6389d2b64f0328364a92323','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--15',1,'{"question":"What is a useful way to compare dances from two cultures?","choices":["Say they are the same because both use rhythm","Rank them by difficulty","Compare specific movement and performance features while preserving their distinct contexts","Ignore who performs them"],"answer":2,"explanation":""}'::jsonb,'4962b4dbb6d20d312fc95560ed824b67','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--16',1,'{"question":"A dance is performed during a community procession. What can its setting contribute?","choices":["It proves the dance has no choreographer","It makes the dance a theater piece only","It determines the tempo","It may connect movement with place, public participation, and occasion"],"answer":3,"explanation":""}'::jsonb,'236eb9585c33cad4573245c784940896','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--17',1,'{"question":"What should a student do if sources disagree about a dance''s origin?","choices":["Report the uncertainty and compare the sources'' evidence and perspectives","Choose the most dramatic story","Invent a single answer","Ignore all sources"],"answer":0,"explanation":""}'::jsonb,'d54af1156618ab270da2c56b16593316','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--18',1,'{"question":"Why might a cultural dance include repeated steps or patterns?","choices":["It proves the dance is simple","Repetition can support participation, structure, or symbolic meaning","It removes the role of music","It guarantees all dancers perform identically"],"answer":1,"explanation":""}'::jsonb,'284ad9c874e5d6df5c6f786c7be1e84b','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--19',1,'{"question":"A dance is taught in a school assembly. What should the teacher consider?","choices":["Whether the dance can be shortened without context","Whether students can imitate costumes","Whether the context and teaching approach represent the tradition respectfully","Whether the tradition is currently popular"],"answer":2,"explanation":""}'::jsonb,'68fa9f57e0c2a7650b26b7c829b2dcbe','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--cultural-dances:fine-arts--dance--cultural-dances--20',1,'{"question":"What is the strongest way to describe a cultural dance?","choices":["Use broad stereotypes","Rely on a single costume image","Assume personal interpretation is fact","Name observable features and explain them using reliable cultural context"],"answer":3,"explanation":""}'::jsonb,'32c632c6f947f6eba0adca23225ec547','official',NULL,NULL,'Cultural Dances'),
('original:fine-arts--dance--choreography-basics:fine-arts--dance--choreography-basics--1',1,'{"question":"What is choreography?","choices":["The composition and organization of movement for a dance","A costume inventory","A music recording device","A type of stage light"],"answer":0,"explanation":""}'::jsonb,'72164f0e94ede275513798254b25a224','official',NULL,NULL,'Choreography Basics'),
('original:fine-arts--dance--choreography-basics:fine-arts--dance--choreography-basics--2',1,'{"question":"A choreographer repeats a short movement idea throughout a dance. What is this idea often called?","choices":["A set piece","A motif","A spotlight","A floor plan"],"answer":1,"explanation":""}'::jsonb,'8c5d8d27fd5e29df32f5eebc87d2cc16','official',NULL,NULL,'Choreography Basics'),
('original:fine-arts--dance--choreography-basics:fine-arts--dance--choreography-basics--3',1,'{"question":"Which structure has two contrasting sections, A and B?","choices":["ABA form","Canon","AB form","Rondo"],"answer":2,"explanation":""}'::jsonb,'25c90d7bf8ccad7458a182959ae2c627','official',NULL,NULL,'Choreography Basics'),
('original:fine-arts--dance--choreography-basics:fine-arts--dance--choreography-basics--4',1,'{"question":"What is ABA form?","choices":["Three unrelated dances performed at once","A line of dancers moving in canon","A rhythm with three beats only","A section returns after a contrasting middle section"],"answer":3,"explanation":""}'::jsonb,'91fa7b2df87971694bf3b5de89226b84','official',NULL,NULL,'Choreography Basics'),
('original:fine-arts--dance--choreography-basics:fine-arts--dance--choreography-basics--5',1,'{"question":"A movement phrase is performed by one dancer, then repeated by others at different times. What device is used?","choices":["Canon","Unison","Mirroring","Stillness"],"answer":0,"explanation":""}'::jsonb,'8b32db3eb36176210b3179695e4fe3eb','official',NULL,NULL,'Choreography Basics'),
