('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--10',1,'{"question":"What is a proscenium stage?","choices":["A stage surrounded by audience on all sides","A stage framed by an architectural opening, with the audience primarily on one side","A platform with no audience","A theater-in-the-round"],"answer":1,"explanation":""}'::jsonb,'1ab607f0d0248d48b0cf5a8776b5a2a9','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--11',1,'{"question":"A performer stands directly in front of another, hiding them from view. What should blocking address?","choices":["The script''s page count","The audience''s program","The actors'' sightlines and spacing","The costume''s fabric"],"answer":2,"explanation":""}'::jsonb,'e3e0eeadaf4917531ed102aeec514d29','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--12',1,'{"question":"How is a thrust stage arranged?","choices":["The audience sits on all four sides","The stage is behind a screen","The audience sits only above the stage","The stage extends into the audience, which sits on three sides"],"answer":3,"explanation":""}'::jsonb,'3346afb4bd8058ceae25dfddfb8320d1','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--13',1,'{"question":"Why might a director pause a scene to adjust a cross?","choices":["To clarify focus, timing, and spatial relationships","To change the play''s historical period","To eliminate all movement","To hide the actors"],"answer":0,"explanation":""}'::jsonb,'412bd55ed30763fba9ed142407c5dc83','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--14',1,'{"question":"What is a stage picture?","choices":["A photograph of the audience","The visual arrangement of performers and scenic elements at a moment","A poster advertising the show","A written character biography"],"answer":1,"explanation":""}'::jsonb,'0637f38078eb547b71ff7d1d67b01ea4','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--15',1,'{"question":"A scene shifts focus from one character to another. How can blocking help?","choices":["Make every actor move at once","Turn all performers away","Use position, movement, or attention to guide the audience''s focus","Remove the scene''s objective"],"answer":2,"explanation":""}'::jsonb,'17f02eaf27f47d7d094820d64baaac86','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--16',1,'{"question":"What does upstage generally mean?","choices":["Toward the audience","To the actor''s right","Above the lighting grid","Away from the audience"],"answer":3,"explanation":""}'::jsonb,'52a12dcceb98915fb1232aa6b5c0ee7e','official',NULL,NULL,'Stage Directions & Blocking')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--17',1,'{"question":"Why is consistent blocking important during a performance run?","choices":["It supports timing, safety, and clear storytelling","It prevents actors from listening","It makes every performance emotionally identical","It changes the playwright''s words"],"answer":0,"explanation":""}'::jsonb,'26457374e85602dd55cb06e277f40111','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--18',1,'{"question":"What should performers do when a planned path conflicts with a prop or set piece?","choices":["Force the prop aside during the scene","Notify the director or stage manager and revise the path safely","Ignore the obstacle","Ask the audience to move it"],"answer":1,"explanation":""}'::jsonb,'ae395f2a7b9bdc9cb2235b352ea15f3d','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--19',1,'{"question":"In a black-box theatre, what is one advantage of flexible seating and staging?","choices":["Every play must use a proscenium","The audience cannot see actors","The performance layout can be adapted to the production","Lighting is unnecessary"],"answer":2,"explanation":""}'::jsonb,'59a9b4bd15b36f0ed25c5325839d8a28','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--stage-directions-blocking:fine-arts--theatre--stage-directions-blocking--20',1,'{"question":"Why should stage directions be interpreted with the scene''s context?","choices":["They always determine one emotion","They replace character analysis","They are unrelated to the story","They guide action but may need to support the play''s objectives and relationships"],"answer":3,"explanation":""}'::jsonb,'238254151a83b0ea3e129c6573abb131','official',NULL,NULL,'Stage Directions & Blocking'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--1',1,'{"question":"What is a character objective?","choices":["What the character wants to achieve in a scene","The actor''s costume size","The play''s publication date","A lighting cue"],"answer":0,"explanation":""}'::jsonb,'52b0c0c9f7b7bd90de191e7afdaccf97','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--2',1,'{"question":"What are given circumstances?","choices":["The audience''s opinions","Facts about the character, setting, and situation established by the play","A list of stage props only","A rehearsal schedule"],"answer":1,"explanation":""}'::jsonb,'1a56845f216d811bed3e6e8e9d9c9b00','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--3',1,'{"question":"What is subtext?","choices":["The printed script''s font","A stage direction in parentheses only","The underlying meaning or feeling beneath the spoken words","A character''s costume"],"answer":2,"explanation":""}'::jsonb,'3bb8912fd86e7fa6df82f5cb5bd6f735','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--4',1,'{"question":"Why should an actor listen and respond to scene partners?","choices":["It removes the need to learn lines","It guarantees the same performance every time","It changes the scene''s setting","Believable interaction depends on responding to what happens in the moment"],"answer":3,"explanation":""}'::jsonb,'2e1d2275a6706a7891811072b760eb72','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--5',1,'{"question":"A character says ''I''m fine'' while avoiding eye contact and gripping a chair. What can the actor consider?","choices":["The words and physical behavior may reveal different layers of meaning","The character has no objective","The scene has ended","The prop determines the dialogue"],"answer":0,"explanation":""}'::jsonb,'a53c3a3a74557e39de5891879a30c614','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--6',1,'{"question":"What is a tactic in acting?","choices":["A costume change","A strategy a character uses to pursue an objective","A stage light","A type of theater"],"answer":1,"explanation":""}'::jsonb,'5375b173dc7fe563278b502f43674740','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--7',1,'{"question":"Why might an actor mark beats in a scene?","choices":["To count the audience","To decide the ticket price","To identify shifts in thought, action, or emotional strategy","To replace rehearsal"],"answer":2,"explanation":""}'::jsonb,'abe2cb0e4ea49d6f05623413c5bccb52','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--8',1,'{"question":"Which action can improve vocal clarity?","choices":["Speak as quietly as possible","Turn away from the audience","Rush every line","Articulate words and support the voice with breath"],"answer":3,"explanation":""}'::jsonb,'e1723ce1bb827af075087a05fd80bda4','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--9',1,'{"question":"What does physicality contribute to characterization?","choices":["The character''s posture, gesture, and movement can communicate traits or intentions","It sets the theater''s seating plan","It replaces the text","It determines the play''s author"],"answer":0,"explanation":""}'::jsonb,'04a683c4850b88900adcff9e06f7ed61','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--10',1,'{"question":"An actor wants to portray nervousness without announcing it. Which choice could help?","choices":["Stand motionless and show no change","Use specific physical behavior such as restless hands or interrupted focus","Read the stage directions aloud","Change the scene''s lighting"],"answer":1,"explanation":""}'::jsonb,'eb46306ddb17bed9c00f4211d47c2cc8','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--11',1,'{"question":"Why rehearse a line with different tactics?","choices":["It changes the play''s genre automatically","It removes the need to understand the scene","It can reveal different ways the character pursues the same objective","It guarantees one tactic is correct"],"answer":2,"explanation":""}'::jsonb,'69602bfaeb6338904cfbce7cab4fdc08','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--12',1,'{"question":"What is a character''s obstacle?","choices":["A stage curtain","The audience''s seat","The actor''s line number","Something that makes achieving the objective difficult"],"answer":3,"explanation":""}'::jsonb,'4f32e8b4639d81280317abb56ebe0ab7','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--13',1,'{"question":"Which question helps an actor analyze a scene?","choices":["What does my character want, and what changes during the scene?","What is the most expensive costume?","How many pages are in the play?","Which audience member arrived first?"],"answer":0,"explanation":""}'::jsonb,'c9ddb63104d7371c5ecd3ecf9e59afa5','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--14',1,'{"question":"Why should actors understand the relationship between characters?","choices":["It determines the theater''s location","It shapes how they speak, move, and respond to one another","It eliminates subtext","It makes every line literal"],"answer":1,"explanation":""}'::jsonb,'1fa130708aeaff37db68b29835857e67','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--15',1,'{"question":"A scene changes after one character reveals a secret. What may this moment be called?","choices":["A costume preset","A prop table","A turning point","A curtain call"],"answer":2,"explanation":""}'::jsonb,'32554ee3d7fd9b6bcd7601b4c7679723','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--16',1,'{"question":"What is projection in acting?","choices":["Shouting every line","Changing the script","Moving a spotlight","Making the voice clear and audible for the performance space"],"answer":3,"explanation":""}'::jsonb,'aa5a7d6f9f077e0d2e851fff211691f2','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--17',1,'{"question":"Why should an actor avoid playing only a broad emotion such as ''angry''?","choices":["Specific objectives and tactics create more detailed, believable behavior","Emotions have no place in acting","The audience cannot notice behavior","Every character must be neutral"],"answer":0,"explanation":""}'::jsonb,'de0137053284dabb0721c04dd9541f3b','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--18',1,'{"question":"How can an actor use a pause?","choices":["As a substitute for every line","As a deliberate moment that can shape thought, tension, or response","To signal a missed cue only","To change the set"],"answer":1,"explanation":""}'::jsonb,'3a29b1f8c38c27f3ebec82f08d08cec4','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--19',1,'{"question":"What does ensemble awareness involve?","choices":["Focusing only on one''s own lines","Ignoring stage spacing","Staying responsive to the whole group and shared performance","Avoiding rehearsal"],"answer":2,"explanation":""}'::jsonb,'aa84b9fc7695b8a3933eeeac59966260','official',NULL,NULL,'Acting Basics'),
('original:fine-arts--theatre--acting-basics:fine-arts--theatre--acting-basics--20',1,'{"question":"A character''s objective is to persuade a friend, but the first tactic fails. What could the actor do?","choices":["Change the scene''s ending without agreement","Stop responding","Repeat the tactic louder indefinitely","Try a different tactic while keeping the objective"],"answer":3,"explanation":""}'::jsonb,'9a8b5d1b4de8b8f72b2683cc091c6e22','official',NULL,NULL,'Acting Basics'),
