('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--2',1,'{"question":"What is an offer in improvisation?","choices":["A ticket price","A verbal or physical contribution that gives a scene information","A costume change","A lighting fixture"],"answer":1,"explanation":""}'::jsonb,'d8c208fe474bc373f03c36d76f937a2a','official',NULL,NULL,'Improvisation Games'),
