('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--6',1,'{"question":"What is a status relationship in improvisation?","choices":["The actors'' rehearsal attendance","A changing difference in power or social position between characters","The theater''s legal status","A type of costume"],"answer":1,"explanation":""}'::jsonb,'38508a87503314f5a5b30902b1843a35','official',NULL,NULL,'Improvisation Games'),
