('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--9',1,'{"question":"What should an improviser do if they make a mistake?","choices":["Stay present and use the moment as new information","Stop and apologize repeatedly","Leave the stage","Blame a partner"],"answer":0,"explanation":""}'::jsonb,'f82a3b308c3dee80075442c62e72fdc2','official',NULL,NULL,'Improvisation Games'),
('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--10',1,'{"question":"In a group improv game, what does ''share focus'' mean?","choices":["Ensure one actor speaks throughout","Make space for different performers to contribute","Avoid looking at partners","Use the same character"],"answer":1,"explanation":""}'::jsonb,'66ff499b3366745e4dd69acfc7a22390','official',NULL,NULL,'Improvisation Games'),
