('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--14',1,'{"question":"What is the purpose of a warm-up game before improvising?","choices":["Determine the final script","Build attention, responsiveness, and group connection","Select the stage curtains","Replace all rehearsal"],"answer":1,"explanation":""}'::jsonb,'098266b96658b51f2858c593af7d92e4','official',NULL,NULL,'Improvisation Games'),
('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--15',1,'{"question":"An improviser asks a partner a question that they could answer with one word, then ignores the answer. What is missing?","choices":["A costume piece","A stage direction","Listening and building on the response","A lighting cue"],"answer":2,"explanation":""}'::jsonb,'838130cb1f0879fcfb0cb26305fcdb63','official',NULL,NULL,'Improvisation Games'),
('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--16',1,'{"question":"Why might performers replay a short improv scene with a different choice?","choices":["To prove the first version was wrong","To avoid listening","To eliminate collaboration","To explore how choices affect the scene''s direction"],"answer":3,"explanation":""}'::jsonb,'1f3efc7f314e4bbd17b7d0a143e641a2','official',NULL,NULL,'Improvisation Games'),
('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--17',1,'{"question":"Which behavior can block a scene?","choices":["Rejecting established information without adding a useful alternative","Accepting an offer","Building a relationship","Clarifying the setting through action"],"answer":0,"explanation":""}'::jsonb,'ba22f83ca45f96b4fcac3b79ea79dd00','official',NULL,NULL,'Improvisation Games'),
('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--18',1,'{"question":"A performer introduces a clear location through gestures and object use. What kind of offer is this?","choices":["A lighting change","A physical or environmental offer","A ticket request","A script edit"],"answer":1,"explanation":""}'::jsonb,'36579d4ece7c46a93c3386eb94c70ce5','official',NULL,NULL,'Improvisation Games'),
('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--19',1,'{"question":"How can an improv group end a scene effectively?","choices":["Stop randomly while a partner speaks","Add unrelated characters until time runs out","Recognize a clear moment of resolution or discovery and finish together","Leave the stage one by one without a cue"],"answer":2,"explanation":""}'::jsonb,'ff8acc5b05b42cf63a8336c44596b8e1','official',NULL,NULL,'Improvisation Games'),
('original:fine-arts--theatre--improvisation-games:fine-arts--theatre--improvisation-games--20',1,'{"question":"What is a useful reflection after an improv game?","choices":["Rate partners by popularity","List only mistakes","Decide who spoke most","Identify which choices supported listening, clarity, and collaboration"],"answer":3,"explanation":""}'::jsonb,'7f1d540a23eb74cb8825d1c01b3d00fc','official',NULL,NULL,'Improvisation Games'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--1',1,'{"question":"What is exposition in a play?","choices":["Information that establishes characters, setting, and situation","The final resolution","A scene change","A costume preset"],"answer":0,"explanation":""}'::jsonb,'7d5eeaee34eec38e233a013fba990a93','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--2',1,'{"question":"What is an inciting incident?","choices":["The last line of the play","An event that sets the central action or conflict in motion","A list of characters","A lighting transition"],"answer":1,"explanation":""}'::jsonb,'eeb389edc376407ccb5ec4bd5a11f07f','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--3',1,'{"question":"Rising action generally includes","choices":["the conflict''s full resolution","only background information","events that build tension and develop the conflict","the audience entering the theater"],"answer":2,"explanation":""}'::jsonb,'1e8a114be2a8e2f1e852919e27ed0627','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--4',1,'{"question":"What is the climax of a dramatic work?","choices":["The opening cast list","A scene with no action","The final costume change","A major turning point or moment of greatest tension"],"answer":3,"explanation":""}'::jsonb,'7642d5da374f1c1677bbc0a3af0d29a2','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--5',1,'{"question":"What usually happens during falling action?","choices":["Consequences of the climax unfold as the story moves toward resolution","The conflict is introduced for the first time","The characters are listed","A new unrelated play begins"],"answer":0,"explanation":""}'::jsonb,'01105676e860ca3de5a0437d807dcd74','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--6',1,'{"question":"What is resolution in dramatic structure?","choices":["The first stage direction","The outcome or settling of the central conflict","A character''s costume","The audience''s reaction"],"answer":1,"explanation":""}'::jsonb,'552edeedafc1ac97c764b870e57f81e5','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--7',1,'{"question":"Why does a play''s conflict matter?","choices":["It sets the theater''s ticket price","It determines the script font","It creates the central tension that drives action","It replaces the characters"],"answer":2,"explanation":""}'::jsonb,'6fc0bf459d6b3f7f8d0676c3dc1d5e25','official',NULL,NULL,'Dramatic Structure'),
