('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--9',1,'{"question":"What is a subplot?","choices":["A secondary storyline that relates to or contrasts with the main plot","A list of stage props","The play''s final resolution","A type of theater seating"],"answer":0,"explanation":""}'::jsonb,'25a36e8eadeffed6b509d8f2756e8d03','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--10',1,'{"question":"A scene ends with new information that changes what the audience expects. What function may it serve?","choices":["Remove the conflict","Create a turning point or increase tension","Establish the ticket price","End the entire play automatically"],"answer":1,"explanation":""}'::jsonb,'bd1b9fe77d524f05b763ba9714dd97dd','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--11',1,'{"question":"Why might a playwright use dramatic irony?","choices":["The play has no audience","Every character knows the same facts","The audience knows information that one or more characters do not","The story contains no tension"],"answer":2,"explanation":""}'::jsonb,'225b8950b3c16ded15cdc74747c1420c','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--12',1,'{"question":"Which sequence best represents a common dramatic arc?","choices":["Resolution, climax, exposition, rising action","Climax, cast list, costume plot, ending","Setting, ticket sale, rehearsal, applause","Exposition, rising action, climax, falling action, resolution"],"answer":3,"explanation":""}'::jsonb,'bba3589dbe5110c31fe665815286495f','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--13',1,'{"question":"A character makes a choice that creates greater difficulty. What can this do to the plot?","choices":["Escalate the conflict","Resolve every problem immediately","Remove the character''s objective","Change the play''s medium"],"answer":0,"explanation":""}'::jsonb,'3a542c7119e52ecf40171e350fb33c54','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--14',1,'{"question":"What is a beat in a scene?","choices":["A theater seat","A small unit of action or a shift in thought or tactic","A costume measurement","A lighting instrument"],"answer":1,"explanation":""}'::jsonb,'7992da5bea31f0194246b92854be13a2','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--15',1,'{"question":"A play opens after a major event has already occurred. What structure may the playwright be using?","choices":["A chronological exposition only","A curtain call","Beginning the action in medias res","A silent tableau"],"answer":2,"explanation":""}'::jsonb,'a722534e4d49b6fddbf5a0c0f34100bb','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--16',1,'{"question":"Why might a playwright delay revealing a key fact?","choices":["To remove all meaning","To avoid developing conflict","To guarantee a happy ending","To create suspense or shape the audience''s understanding"],"answer":3,"explanation":""}'::jsonb,'5c8cf74d82a8c8e59b43ff069096ec13','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--17',1,'{"question":"What is a tragic flaw in traditional dramatic analysis?","choices":["A character trait or error that contributes to the character''s downfall","A mistake made by the stage crew","A missing costume","A type of lighting cue"],"answer":0,"explanation":""}'::jsonb,'b20b09e078aeb03b693ed27905c9771b','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--18',1,'{"question":"How can a scene''s objective connect to the larger dramatic structure?","choices":["It always determines the play''s title","The character''s immediate goal can advance or complicate the main conflict","It replaces the setting","It prevents a climax"],"answer":1,"explanation":""}'::jsonb,'766d65d7875efbc171e89e27332eca47','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--19',1,'{"question":"A final scene answers the central question but leaves a new issue open. What can this create?","choices":["A broken dramatic structure by definition","An exposition with no conflict","A sense of closure alongside continued possibility","A missing audience"],"answer":2,"explanation":""}'::jsonb,'5f7323f8fa279ad82ecc87d0b8faea5b','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--dramatic-structure:fine-arts--theatre--dramatic-structure--20',1,'{"question":"When analyzing a play''s structure, what evidence is most useful?","choices":["Only the number of pages","Only the costumes","The theater''s location","Events, turning points, conflicts, and their effects on characters"],"answer":3,"explanation":""}'::jsonb,'97aa8c6c73da4af509c2efee5c4fd6bb','official',NULL,NULL,'Dramatic Structure'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--1',1,'{"question":"What does a stage play''s dialogue consist of?","choices":["The spoken words assigned to characters","The lighting plan","The costume inventory","The audience''s program"],"answer":0,"explanation":""}'::jsonb,'fb2d9910a7d6868ae215fbbe32403e6e','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--2',1,'{"question":"What is a stage direction?","choices":["A character''s spoken line","A written instruction about action, setting, or performance","A ticket price","A review of the play"],"answer":1,"explanation":""}'::jsonb,'a0ac0a166c1d90aee547c109d1bb53ae','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--3',1,'{"question":"Why should dialogue sound appropriate to a character and situation?","choices":["It guarantees every character speaks the same way","It removes the need for conflict","It helps reveal voice, relationship, and context","It determines the stage''s size"],"answer":2,"explanation":""}'::jsonb,'ce1e65e6a400baf929605bafbc9fbe56','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--4',1,'{"question":"A character says, ''I didn''t take it,'' while hiding an object. What can this create?","choices":["A scene change","A lighting cue","A cast list","Subtext or dramatic irony"],"answer":3,"explanation":""}'::jsonb,'a54bea8af04b9f112e676faeb49a609f','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--5',1,'{"question":"What is one purpose of a pause in dialogue?","choices":["Create emphasis, tension, or time for a response","Replace every stage direction","End the play automatically","Set the costume color"],"answer":0,"explanation":""}'::jsonb,'51e883b0c4244a9e4f7064a1b9c219a0','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--6',1,'{"question":"Which line best reveals a character''s goal through dialogue?","choices":["Hello, the room is large","I need to convince the council before the vote begins","The chair is wooden","That is a word"],"answer":1,"explanation":""}'::jsonb,'02c3a933e492c096fd10042b6e227068','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--7',1,'{"question":"Why read dialogue aloud during revision?","choices":["To measure the stage","To choose a lighting gel","To hear whether it sounds speakable and reveals the intended rhythm","To avoid editing the script"],"answer":2,"explanation":""}'::jsonb,'800b473ff1fdb4060180522d51a66fcf','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--8',1,'{"question":"What is a monologue?","choices":["A conversation between two characters","A change of scene","A list of props","An extended speech by one character"],"answer":3,"explanation":""}'::jsonb,'390234d087701ee9b20cd8ed9163bcda','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--9',1,'{"question":"What is an aside in theatre?","choices":["A brief remark intended for the audience or not heard by other characters","A stage entrance","A costume change","A line spoken by the chorus only"],"answer":0,"explanation":""}'::jsonb,'e5e7171aa2c51147ea3683271ae93c77','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--10',1,'{"question":"A script has long speeches that all provide background facts. What could improve them?","choices":["Add more facts to each speech","Break information into purposeful exchanges shaped by character objectives","Remove every character response","Use the same voice for all characters"],"answer":1,"explanation":""}'::jsonb,'3f45fc1097c1efed756a88beb9599a2c','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--11',1,'{"question":"What is a beat in scriptwriting?","choices":["A page number","A stage platform","A small shift in action, thought, or tactic within a scene","A costume fitting"],"answer":2,"explanation":""}'::jsonb,'47b452f1275f448748af9018f1227760','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--12',1,'{"question":"Why should a playwright consider what a character does not say?","choices":["Unspoken ideas have no dramatic effect","Every character must explain every thought","Silence removes all conflict","Silence and omission can shape tension or reveal subtext"],"answer":3,"explanation":""}'::jsonb,'96d0089539744a4703b728c3da5fb32f','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--13',1,'{"question":"Which dialogue is most likely to create conflict?","choices":["You promised to keep it secret. I had to tell someone.","The lamp is on. Yes, it is.","We arrived at noon. It was noon.","The door is open. The door is open."],"answer":0,"explanation":""}'::jsonb,'ef32a6ddadf21600375372cf0ca6c612','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--14',1,'{"question":"What is a useful way to format a script for rehearsal?","choices":["Place all text in one unlabeled paragraph","Clearly distinguish character names, dialogue, and stage directions","Hide character names","Remove scene divisions"],"answer":1,"explanation":""}'::jsonb,'731fa31becd54426fe4f172e54f50160','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--15',1,'{"question":"A playwright wants a character''s status to change in a conversation. What can the dialogue show?","choices":["A new costume only","A change in theater architecture","A shift in who persuades, controls information, or sets the terms","The audience''s exact age"],"answer":2,"explanation":""}'::jsonb,'fd3a939ff66db83bbff80a077e0ad2b5','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--16',1,'{"question":"Why should stage directions avoid unnecessary detail?","choices":["Actors cannot read directions","Playwrights may not describe action","Directions replace dialogue","They should support the action while leaving room for performance choices"],"answer":3,"explanation":""}'::jsonb,'13d55620c3d46ad19154b2eacf9703bb','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--17',1,'{"question":"What is a dialogue tag or cue used for in a script?","choices":["Identify which character speaks","Set the ticket price","Describe the audience","Name the theater"],"answer":0,"explanation":""}'::jsonb,'6226bd2d5e22c975dcce465b3cdd2354','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--18',1,'{"question":"A character''s speech uses short, interrupted sentences during an argument. What might this choice communicate?","choices":["A quiet setting by itself","Tension or difficulty completing thoughts","A change in costume","The number of scenes"],"answer":1,"explanation":""}'::jsonb,'e7a1090cad32d59a818212cd94d724db','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--19',1,'{"question":"How can revision improve dialogue?","choices":["Make every character use identical phrasing","Add unrelated explanation","Remove repetition that does not reveal character or advance the scene","Avoid reading the lines aloud"],"answer":2,"explanation":""}'::jsonb,'362f1ffcdca0b32ff93ca3f717166e29','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--scriptwriting-dialogue:fine-arts--theatre--scriptwriting-dialogue--20',1,'{"question":"What is the strongest test of a stage direction?","choices":["Is it longer than the dialogue?","Does it name every audience member?","Does it explain the play''s marketing plan?","Does it help performers or readers understand an action necessary to the scene?"],"answer":3,"explanation":""}'::jsonb,'e04843d3bae8451cb60578d76c3e664e','official',NULL,NULL,'Scriptwriting & Dialogue'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--1',1,'{"question":"What is a character trait?","choices":["A relatively consistent quality shown through choices or behavior","A stage prop","A scene transition","A theater seat"],"answer":0,"explanation":""}'::jsonb,'783e40130ab45e10b9725861bb1afbac','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--2',1,'{"question":"How can an audience learn about a character without direct description?","choices":["Read the ticket price","Observe the character''s actions, dialogue, and responses","Count the stage lights","Inspect the curtain"],"answer":1,"explanation":""}'::jsonb,'f3c0911608636a5333b5f1dc62e3c692','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--3',1,'{"question":"What does a character arc describe?","choices":["The shape of the stage","The order of costumes","How a character changes or develops over the course of a story","A line in the script"],"answer":2,"explanation":""}'::jsonb,'62b56e5c430365b379eac8a797749485','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--4',1,'{"question":"A character begins fearful of speaking up and later challenges an unfair rule. What has changed?","choices":["The play''s setting","The audience''s seating","The character''s costume alone","The character''s confidence or willingness to act"],"answer":3,"explanation":""}'::jsonb,'46d008a37fdac52688128f60c9e293d9','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--5',1,'{"question":"Why is an objective important to character development?","choices":["It gives the character something to pursue and shapes choices","It sets the scene''s lighting","It determines the play''s length","It replaces obstacles"],"answer":0,"explanation":""}'::jsonb,'3946ded21fefe79fc251ef8693e9ea2b','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--6',1,'{"question":"Which detail best reveals a character''s generosity?","choices":["She owns a blue coat","She gives her only dry coat to a neighbor during the storm","She enters from stage left","She is named in the cast list"],"answer":1,"explanation":""}'::jsonb,'e509ba207237f8e6a70e9a2242f0eb98','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--7',1,'{"question":"What is a motivation?","choices":["A costume label","A lighting cue","A reason or need that helps explain a character''s action","A stage measurement"],"answer":2,"explanation":""}'::jsonb,'f89858189e80cbea361f89bf42137a46','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--8',1,'{"question":"A character repeatedly avoids a conversation but finally initiates it. What can the change reveal?","choices":["A change in theater style","The audience''s reaction","A new lighting instrument","A shift in the character''s willingness or priorities"],"answer":3,"explanation":""}'::jsonb,'7b1d819fcb331d7d8116fa810979d4d6','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--9',1,'{"question":"Why should characters have both strengths and limitations?","choices":["Complex traits can make their choices and conflicts more believable","Every character must be a hero","Limitations remove the plot","Strengths prevent change"],"answer":0,"explanation":""}'::jsonb,'786035be7841bef5227957f067a4cf67','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--10',1,'{"question":"A character wants to protect a friend but also tell the truth. What does this create?","choices":["A stage direction","An internal conflict between competing values or goals","A costume change","A resolution with no choice"],"answer":1,"explanation":""}'::jsonb,'7773e01599aa53677cb9fc29860fe64e','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--11',1,'{"question":"What is backstory?","choices":["The scenery behind an actor","A scene performed backward","Relevant events from a character''s past","An audience seating chart"],"answer":2,"explanation":""}'::jsonb,'e9d3e5c227c8dd00f917782550abc7c7','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--12',1,'{"question":"Why should backstory be revealed selectively?","choices":["The audience should know every fact immediately","Past events cannot affect a play","Backstory replaces the current action","It is most useful when it deepens present choices or relationships"],"answer":3,"explanation":""}'::jsonb,'84b6e1ede141f072def21546932f2b38','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--13',1,'{"question":"A character is described as brave, but consistently avoids every risk. What should a playwright revise?","choices":["Align the description with the character''s actions or show the contradiction intentionally","Remove all action","Change the theater''s location","Add an unrelated character"],"answer":0,"explanation":""}'::jsonb,'60d268b21e78e1bfcb7ceb6e9bfdd4ba','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--14',1,'{"question":"How can relationships reveal character?","choices":["Relationships affect only costumes","The way a character treats different people can show values and priorities","Every character behaves identically with everyone","Relationships remove objectives"],"answer":1,"explanation":""}'::jsonb,'017ac5e44eb0223201c27e55edebf928','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--15',1,'{"question":"A character changes their mind after hearing new evidence. What supports a believable arc?","choices":["Make the change happen without context","Hide the character''s earlier view","Show what evidence or experience influenced the change","Remove the conflict"],"answer":2,"explanation":""}'::jsonb,'448cf3beb62c6ecd54046aaeacc917e6','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--16',1,'{"question":"What is a foil character?","choices":["A stage manager","A costume designer","A narrator who speaks every line","A character whose contrasting qualities help highlight another character"],"answer":3,"explanation":""}'::jsonb,'644157ad261fb3f45f8c8387615f1035','official',NULL,NULL,'Character Development')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--17',1,'{"question":"Which question best supports character analysis?","choices":["What does the character want, and how do their choices affect others?","How many chairs are on stage?","What is the play''s print size?","Which ticket section is cheapest?"],"answer":0,"explanation":""}'::jsonb,'3a37123acc06badf82e317d789b5817a','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--18',1,'{"question":"A character''s public behavior differs from private thoughts. What can this create?","choices":["A lighting cue","Complexity between outward presentation and inner experience","A new scene location","A change in the script format"],"answer":1,"explanation":""}'::jsonb,'04d08892457e59b9a299825597d74732','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--19',1,'{"question":"Why should a character''s choices have consequences?","choices":["They guarantee a tragic ending","They remove audience interpretation","Consequences help connect actions to the story''s development","They replace dialogue"],"answer":2,"explanation":""}'::jsonb,'9a448fdba89263ac6ea87f7238dbb2f1','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--character-development:fine-arts--theatre--character-development--20',1,'{"question":"Which statement best describes realistic character development?","choices":["A character changes randomly in every scene","A character never makes choices","A change is explained only by costume","A change is supported by experiences, choices, and relationships in the story"],"answer":3,"explanation":""}'::jsonb,'45e3967b42c72749abca097b09bb7904','official',NULL,NULL,'Character Development'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--1',1,'{"question":"What is a set designer''s primary responsibility?","choices":["Create the visual and physical environment for a production","Write every line","Manage ticket sales","Choose the audience"],"answer":0,"explanation":""}'::jsonb,'fb812af96d9f1592374f978ec216e418','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--2',1,'{"question":"What can a set help communicate?","choices":["The exact thoughts of every audience member","Location, time period, mood, and practical acting space","The play''s copyright status","The actors'' grades"],"answer":1,"explanation":""}'::jsonb,'852701a4bf693eda1add3fd1f0420b9a','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--3',1,'{"question":"What does a costume designer consider when designing clothing for a character?","choices":["Only the actor''s favorite color","The number of theater seats","Character, setting, movement, fabric, and production needs","The ticket price"],"answer":2,"explanation":""}'::jsonb,'9e76a69443cb4872c7fb4047b2282876','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--4',1,'{"question":"Why should a costume allow safe movement?","choices":["Costumes should restrict all movement","Safety is unrelated to design","A costume replaces rehearsal","Performers need to execute choreography and blocking without unnecessary risk"],"answer":3,"explanation":""}'::jsonb,'34a0cc0d5a5d82e19ad348927b1a65fb','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--5',1,'{"question":"A production uses one chair to represent a throne, a bus seat, and a kitchen chair. What design approach is this?","choices":["A flexible prop or set piece used to suggest multiple locations","A realistic set with a separate chair for each scene","A costume plot","A lighting cue"],"answer":0,"explanation":""}'::jsonb,'36f273f4c7df5450d4e18ed615ea5c0a','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--6',1,'{"question":"What is a scenic model used for?","choices":["Record actor dialogue","Plan and communicate the design''s scale, layout, and visual elements","Manage the audience","Write a character arc"],"answer":1,"explanation":""}'::jsonb,'568ac7a9783862178ede7d3453ca8a02','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--7',1,'{"question":"Why must designers collaborate with directors and performers?","choices":["Designers control every actor''s performance","Collaboration removes creative choices","Design choices need to support the production''s concept and practical staging","Only the director uses scenery"],"answer":2,"explanation":""}'::jsonb,'531933259253badd718593b73bdb668c','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--8',1,'{"question":"A set wall blocks the audience''s view of a key action. What should the design team reconsider?","choices":["The script''s title","The costume''s color","The actors'' biographies","Sightlines and scenic placement"],"answer":3,"explanation":""}'::jsonb,'3653a01626ac5ad7d2c1ea2a1ee0255b','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--9',1,'{"question":"What does a costume plot track?","choices":["Which costumes each performer wears in each scene","Where each audience member sits","The lighting equipment","The play''s ticket income"],"answer":0,"explanation":""}'::jsonb,'44cc26a96c23a2403b37a623b50a3e71','official',NULL,NULL,'Set & Costume Design'),
('original:fine-arts--theatre--set-costume-design:fine-arts--theatre--set-costume-design--10',1,'{"question":"Why might a costume designer use color intentionally?","choices":["Color always identifies a character''s morality","Color can support character, mood, contrast, or visual focus","Color is unrelated to design","All costumes must be the same color"],"answer":1,"explanation":""}'::jsonb,'76192dac612993caf0f23b8524d45044','official',NULL,NULL,'Set & Costume Design'),
