('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--5',1,'{"question":"What does texture describe in a visual artwork?","choices":["The actual or suggested surface quality","The object''s exact location","The hue of a color","The size of the canvas"],"answer":0,"explanation":""}'::jsonb,'ca84cee8ca7dc0f9f450738a01f41a5d','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--6',1,'{"question":"What is space in an artwork?","choices":["The artwork''s title","The area around, between, or within forms","The color''s brightness only","A type of brush"],"answer":1,"explanation":""}'::jsonb,'9b6b919ab383accc5b85b05a8b21c584','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--7',1,'{"question":"What is hue?","choices":["The amount of light in a room","The roughness of paper","The name of a color, such as red or blue","The direction of a shape"],"answer":2,"explanation":""}'::jsonb,'b9adeee45195b421932fa18b211f5769','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--8',1,'{"question":"How can overlapping forms suggest depth?","choices":["Both forms become flat symbols","The colors become complementary","The composition loses space","The overlapping form appears closer than the one it covers"],"answer":3,"explanation":""}'::jsonb,'59542831123a401002f2bce4967585cb','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--9',1,'{"question":"Which element can make a flat circle appear spherical?","choices":["Value through highlights and shadows","A thicker frame","A title card","A repeated outline only"],"answer":0,"explanation":""}'::jsonb,'7193907eae15f98e466742ae84f84dac','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--10',1,'{"question":"A drawing uses repeated diagonal lines. Which element is most evident?","choices":["Form","Line","Space","Texture only"],"answer":1,"explanation":""}'::jsonb,'1615a23304b60e8586802b7fd340befa','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--11',1,'{"question":"What is implied texture?","choices":["A physically rough surface only","A color that has been mixed","A visual suggestion of how a surface might feel","An object shown in perspective"],"answer":2,"explanation":""}'::jsonb,'c20594b20171461ca513a832934bc000','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--12',1,'{"question":"How can negative space help a composition?","choices":["It removes all objects","It changes the medium","It guarantees symmetry","It clarifies shapes and relationships by giving forms room"],"answer":3,"explanation":""}'::jsonb,'616559aa2b48c1d858a94b13f0fbe57b','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--13',1,'{"question":"What is a geometric shape?","choices":["A shape based on precise forms such as circles or rectangles","A shape found only in nature","A three-dimensional sculpture","A color without a name"],"answer":0,"explanation":""}'::jsonb,'feb0419be997c34e7e021f4c56886903','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--14',1,'{"question":"Which example best shows organic shape?","choices":["A perfect square","An irregular leaf silhouette","A measured grid","A straight ruler line"],"answer":1,"explanation":""}'::jsonb,'d1b4b9e5837f1b76fd2c28c647b31ca9','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--15',1,'{"question":"Why might an artist vary line weight?","choices":["To change the artwork''s subject","To make every area equally important","To create emphasis, depth, or visual movement","To remove contour"],"answer":2,"explanation":""}'::jsonb,'649c5363c795e22cdeea3332e906bfda','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--16',1,'{"question":"What does a highlight usually indicate in a modeled form?","choices":["The darkest region","A cast shadow on the floor","The object''s outline","An area receiving stronger light"],"answer":3,"explanation":""}'::jsonb,'55672244242dc1f542094c29e70028c2','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--17',1,'{"question":"How can texture contribute to meaning?","choices":["Surface qualities can suggest material, mood, or sensory experience","Texture always identifies the artist","Texture replaces composition","Texture determines the artwork''s age"],"answer":0,"explanation":""}'::jsonb,'c72b97cbf14d1d2349428df230843aa8','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--18',1,'{"question":"What is the difference between actual and implied texture?","choices":["Actual texture is always smooth; implied is rough","Actual texture can be physically felt; implied texture is visually represented","Actual is color; implied is line","There is no difference"],"answer":1,"explanation":""}'::jsonb,'bfa27deb66cf0c4fd6eeaf10e7be5818','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--19',1,'{"question":"A still life has objects that seem to float. Which element may need clearer development?","choices":["Hue only","The artwork''s signature","Space and relationships among forms","The frame material"],"answer":2,"explanation":""}'::jsonb,'48280483521c294c5c590eb14fe953e1','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--elements-of-art:fine-arts--visual-arts--elements-of-art--20',1,'{"question":"Why do artists study elements of art?","choices":["They prescribe one correct style","They eliminate interpretation","They replace practice with memorization","They provide vocabulary for making and analyzing visual choices"],"answer":3,"explanation":""}'::jsonb,'1b6abd62b2870a56b3c2eee5c299d006','official',NULL,NULL,'Elements of Art'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--1',1,'{"question":"What does balance describe in a composition?","choices":["How visual weight is distributed","The artwork''s physical weight","The number of colors used","The artist''s drawing speed"],"answer":0,"explanation":""}'::jsonb,'03294ef6aa1e8f05c97346804e787e63','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--2',1,'{"question":"What is contrast?","choices":["A repeated shape with no changes","A noticeable difference between visual elements","The space behind a frame","A type of paint"],"answer":1,"explanation":""}'::jsonb,'05332d9e7ed8006e7eeff1c98e12ffc4','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--3',1,'{"question":"How can emphasis guide a viewer?","choices":["It makes every area identical","It removes focal points","It makes one area or idea stand out","It determines the artwork''s scale"],"answer":2,"explanation":""}'::jsonb,'a2d2766aceb1d019ea99e5b0f03f7e65','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--4',1,'{"question":"What does rhythm create in visual art?","choices":["A literal sound beat in every artwork","A balanced frame","A fixed color temperature","A sense of movement through repeated or varied elements"],"answer":3,"explanation":""}'::jsonb,'18146738b6bb5faec08866809e1b2053','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--5',1,'{"question":"What is pattern?","choices":["A repeated decorative or structural design","A single focal point","A type of perspective","A color''s brightness"],"answer":0,"explanation":""}'::jsonb,'ee3d6528ef6b7b7d21a2f0f7a74a557e','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--6',1,'{"question":"What does proportion compare?","choices":["The number of materials","The relative size of parts to one another or to the whole","The canvas orientation","The contrast of hues"],"answer":1,"explanation":""}'::jsonb,'9b366992afdd08332364c0079b666d9e','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--7',1,'{"question":"How does unity contribute to a design?","choices":["It makes every element the same size","It removes variation","It makes parts feel connected as a coherent whole","It guarantees symmetry"],"answer":2,"explanation":""}'::jsonb,'033671811d3de94f87675ddd81e914d5','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--8',1,'{"question":"What is variety in design?","choices":["A strict repetition with no changes","An exact measurement of scale","A rule that removes focal points","Differences that add interest within a composition"],"answer":3,"explanation":""}'::jsonb,'b187af0dd5e81654c3df1352d589f9c5','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--9',1,'{"question":"A poster''s title is hard to notice. Which principle could improve it?","choices":["Emphasis through stronger size, contrast, or placement","Pattern through repetition only","Unity through matching the background","Balance through equal font sizes"],"answer":0,"explanation":""}'::jsonb,'07243d32405bdc6cc6899f644ca5ed75','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--10',1,'{"question":"What does movement describe in design?","choices":["How the artwork physically changes","How a viewer''s eye travels through the composition","The artist''s process speed","A sculpture''s weight"],"answer":1,"explanation":""}'::jsonb,'c080db6963d03eb210e4e5ed220a89ea','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--11',1,'{"question":"Which arrangement can create asymmetrical balance?","choices":["Two identical halves reflected across a center","Every shape in one corner","Different elements with visual weights that still feel stable","A design with no focal point"],"answer":2,"explanation":""}'::jsonb,'3a7cc3d791e7876d0453023559c68e9b','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--12',1,'{"question":"Why might a designer use repetition with variation?","choices":["To eliminate all structure","To make each element unrelated","To remove emphasis","To establish unity while keeping the composition engaging"],"answer":3,"explanation":""}'::jsonb,'37840564323a0ea17762a6bfed3e9268','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--13',1,'{"question":"What does scale describe?","choices":["The size of an element in relation to another or its surroundings","The surface texture","The color''s hue","The number of brush strokes"],"answer":0,"explanation":""}'::jsonb,'9a58b244c99034395e67997e65fba0ba','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--14',1,'{"question":"A composition feels crowded. What revision may improve balance and clarity?","choices":["Add more decoration everywhere","Adjust spacing and visual weight among the elements","Make every item equally bold","Remove all negative space"],"answer":1,"explanation":""}'::jsonb,'7068cf31f003a75c769ba1e1ae6a8447','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--15',1,'{"question":"How are contrast and emphasis related?","choices":["They are identical to proportion","Contrast always removes focus","Contrast can help create emphasis by making an element distinct","Emphasis depends only on size"],"answer":2,"explanation":""}'::jsonb,'7066d78281f1757b8136caab75c9150e','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--16',1,'{"question":"What is an example of visual rhythm?","choices":["A single object with no repetition","A note played in a song","A color''s temperature","A repeated sequence of shapes that leads the eye across a page"],"answer":3,"explanation":""}'::jsonb,'c83683441e382e249ba7a5f40374b7d8','official',NULL,NULL,'Principles of Design')
insert into public.question_content_versions(source_key,version_number,question,content_hash,source_type,creator_id,source_set_id,source_title) values
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--17',1,'{"question":"Why is unity not the same as sameness?","choices":["A unified design can connect varied elements through shared relationships","Unity requires all parts to be identical","Variation prevents all unity","Unity only occurs in symmetrical designs"],"answer":0,"explanation":""}'::jsonb,'559e42a0e6611c0058b622f1b0b2b264','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--18',1,'{"question":"Which principle is most directly involved when a focal image dominates a layout?","choices":["Pattern","Emphasis","Proportion","Rhythm"],"answer":1,"explanation":""}'::jsonb,'913b930d38f922b7bc44ed44f89777fd','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--19',1,'{"question":"How can negative space support a design''s hierarchy?","choices":["It makes all items equal","It removes the need for alignment","It separates groups and gives important content room to stand out","It changes the artwork''s medium"],"answer":2,"explanation":""}'::jsonb,'ab13eb531fdf3e2b611a4eaf6d988287','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--principles-of-design:fine-arts--visual-arts--principles-of-design--20',1,'{"question":"What should an artist consider when choosing design principles?","choices":["A fixed rule that all principles must be equal","The frame color only","How many supplies remain","The intended idea, audience, and relationships among visual elements"],"answer":3,"explanation":""}'::jsonb,'6bc403a0b13a250ba931a77aefebb820','official',NULL,NULL,'Principles of Design'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--1',1,'{"question":"What are the primary colors in the traditional subtractive painting model?","choices":["Red, yellow, and blue","Red, green, and blue","Orange, green, and violet","Black, white, and gray"],"answer":0,"explanation":""}'::jsonb,'96240ffa8cf230daa96bac9d62039c6d','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--2',1,'{"question":"What color results from mixing blue and yellow pigment?","choices":["Violet","Green","Orange","Red"],"answer":1,"explanation":""}'::jsonb,'949c978317f4f4ca3771aebcdd52e7d9','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--3',1,'{"question":"What are complementary colors?","choices":["Colors next to each other","Colors with identical hue","Colors opposite each other on a color wheel","All neutral colors"],"answer":2,"explanation":""}'::jsonb,'887ccdddedd16707e9e241ea1b4e7e45','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--4',1,'{"question":"What effect can complementary colors create when placed together?","choices":["A guaranteed neutral result","Less contrast than analogous colors","A change in value only","Strong contrast and visual energy"],"answer":3,"explanation":""}'::jsonb,'42e5431b8d2616849d90581111fdf532','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--5',1,'{"question":"What are analogous colors?","choices":["Colors next to one another on the color wheel","Colors opposite one another","Only primary colors","Colors with no shared properties"],"answer":0,"explanation":""}'::jsonb,'c5ffd89dbdd113c3afcf5530263520a9','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--6',1,'{"question":"What is hue?","choices":["How light or dark it is","A color''s basic family or name","How muted or intense it is","The surface it is painted on"],"answer":1,"explanation":""}'::jsonb,'9895eab370604f34da473cd5a099c7da','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--7',1,'{"question":"What does value describe in color?","choices":["Its place on the wheel only","Its warmth only","Its relative lightness or darkness","The amount of pigment in a tube"],"answer":2,"explanation":""}'::jsonb,'8f2888bae69ede1e81fbc99d1c4517c7','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--8',1,'{"question":"What does saturation describe?","choices":["The object''s size","The direction of the light","The color''s temperature only","The intensity or purity of a color"],"answer":3,"explanation":""}'::jsonb,'e845c09646dc62d95eb1ef6008dc9b09','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--9',1,'{"question":"How can adding white to a hue affect it?","choices":["Create a tint","Create a shade","Create a complementary color","Remove the hue"],"answer":0,"explanation":""}'::jsonb,'67604bbfd48e653c3562dfe4bffb2e8e','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--10',1,'{"question":"How can adding black to a hue affect it?","choices":["Create a tint","Create a shade","Create an analogous color","Increase its brightness"],"answer":1,"explanation":""}'::jsonb,'96e65c45a62846a1123a8e61bd7ae4ac','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--11',1,'{"question":"What are warm colors often associated with in a composition?","choices":["A guaranteed calm mood","Distance in every context","Energy, warmth, or visual closeness","No emotional effect"],"answer":2,"explanation":""}'::jsonb,'5f444b3a903f441e3bda303603a77a68','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--12',1,'{"question":"Why should artists consider color contrast for readable text?","choices":["Contrast always improves every palette","Text color determines the paper size","Low contrast makes all details clearer","Sufficient contrast helps viewers distinguish text from its background"],"answer":3,"explanation":""}'::jsonb,'c3eae0b73ec2ef51f0c566f2f1c3e0bf','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--13',1,'{"question":"What is a neutral color?","choices":["A color such as gray, black, white, or brown that is less strongly associated with a hue","Any color mixed from two primaries","A color that is always bright","A complementary pair"],"answer":0,"explanation":""}'::jsonb,'48a52fa45cca381e897095a197554f28','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--14',1,'{"question":"A painting feels overly intense. Which change may soften the palette?","choices":["Increase saturation everywhere","Use less saturated colors or add neutral mixtures","Remove all value changes","Use only complementary pairs at full intensity"],"answer":1,"explanation":""}'::jsonb,'6330245298bc27a8822dc1cb55255b24','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--15',1,'{"question":"What is color temperature?","choices":["The physical heat of paint","A color''s brightness level","The perceived warmth or coolness of a color","The amount of water in a brush"],"answer":2,"explanation":""}'::jsonb,'271ab510a466db0d215c0ee42fbe845a','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--16',1,'{"question":"Which pair is complementary in the traditional color wheel?","choices":["Blue and green","Yellow and orange","Red and orange","Blue and orange"],"answer":3,"explanation":""}'::jsonb,'141f2b8a79672368a71b143545cc16ee','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--17',1,'{"question":"How can a limited palette help an artist?","choices":["It can create harmony and focus choices","It guarantees realistic color","It prevents all contrast","It removes the need for value"],"answer":0,"explanation":""}'::jsonb,'5df052c147a585d78570ec1ebe1483c9','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--18',1,'{"question":"Why can color meaning vary across contexts?","choices":["Every color has one universal meaning","Culture, setting, and personal experience influence interpretation","Color meaning depends only on pigment brand","Context affects value but not meaning"],"answer":1,"explanation":""}'::jsonb,'e617b3675e22bf4090899927aedcc198','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--19',1,'{"question":"What is simultaneous contrast?","choices":["A pair of colors mixed together","The difference between two canvases","A color can appear different depending on the colors around it","An effect created only by black paint"],"answer":2,"explanation":""}'::jsonb,'4b2c6826e78b9f44bded57cc6a21b912','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--color-theory:fine-arts--visual-arts--color-theory--20',1,'{"question":"A designer wants an alert to stand out from a blue background. What is a reasonable strategy?","choices":["Use nearly the same blue value","Reduce all contrast","Put the alert in the smallest type","Choose a contrasting hue and check readability"],"answer":3,"explanation":""}'::jsonb,'941c91c26752352d61a2eef3f6b4c8aa','official',NULL,NULL,'Color Theory'),
('original:fine-arts--visual-arts--drawing-basics:fine-arts--visual-arts--drawing-basics--1',1,'{"question":"What is contour drawing?","choices":["Drawing the visible edges and outlines of a subject","Shading only the background","Measuring color temperature","Cutting shapes from paper"],"answer":0,"explanation":""}'::jsonb,'6dbd4613c90f8cb7559c194ec6faa04c','official',NULL,NULL,'Drawing Basics'),
('original:fine-arts--visual-arts--drawing-basics:fine-arts--visual-arts--drawing-basics--2',1,'{"question":"Why use gesture drawing?","choices":["To add final surface detail","To capture a subject''s action, movement, and overall pose quickly","To choose a frame","To copy every contour exactly"],"answer":1,"explanation":""}'::jsonb,'bcb4b99f4c02e07a6c06c24dc80b0eef','official',NULL,NULL,'Drawing Basics'),
('original:fine-arts--visual-arts--drawing-basics:fine-arts--visual-arts--drawing-basics--3',1,'{"question":"What is a vanishing point in linear perspective?","choices":["The darkest point in a drawing","The center of a circle","A point where parallel lines appear to meet in the distance","A point where a pencil is sharpened"],"answer":2,"explanation":""}'::jsonb,'4c7fe81fbb53578f9bb9b80361733118','official',NULL,NULL,'Drawing Basics'),
('original:fine-arts--visual-arts--drawing-basics:fine-arts--visual-arts--drawing-basics--4',1,'{"question":"How does a horizon line relate to perspective drawing?","choices":["It marks the paper''s bottom edge","It indicates the darkest shadow","It shows the subject''s height","It represents the viewer''s eye level"],"answer":3,"explanation":""}'::jsonb,'7a6bb5a62ff84f0c7b8e8c8fb4d7b74d','official',NULL,NULL,'Drawing Basics'),
('original:fine-arts--visual-arts--drawing-basics:fine-arts--visual-arts--drawing-basics--5',1,'{"question":"What does shading help communicate?","choices":["Form, light, and depth","The subject''s name","The page''s orientation","A line''s direction only"],"answer":0,"explanation":""}'::jsonb,'ae2afb1cf939d9ec96e56a6cf3f70ffe','official',NULL,NULL,'Drawing Basics'),
('original:fine-arts--visual-arts--drawing-basics:fine-arts--visual-arts--drawing-basics--6',1,'{"question":"A cylinder looks flat. What can help show its volume?","choices":["A single straight outline only","An elliptical top and gradual value changes","A brighter signature","A thicker paper"],"answer":1,"explanation":""}'::jsonb,'d854dfc0ef83cc994220d67dc3f740f4','official',NULL,NULL,'Drawing Basics'),
