('original:fine-arts--visual-arts--sculpture-3d-art:fine-arts--visual-arts--sculpture-3d-art--11',1,'{"question":"What is a mobile in sculpture?","choices":["A sculpture carved from a single block","A type of wall relief","A balanced construction with parts that move freely","A model of a cell phone"],"answer":2,"explanation":""}'::jsonb,'33b9f52b68199f5ea4ba1a4dfd3794e6','official',NULL,NULL,'Sculpture & 3D Art'),
('original:fine-arts--visual-arts--sculpture-3d-art:fine-arts--visual-arts--sculpture-3d-art--12',1,'{"question":"Why is material choice important in a public sculpture?","choices":["Only the material''s color matters","The material determines the audience","All materials last equally outdoors","Weather, durability, weight, access, and maintenance affect the design"],"answer":3,"explanation":""}'::jsonb,'2e7a15e4b1fb597211e3fef604e58a43','official',NULL,NULL,'Sculpture & 3D Art'),
