('original:fine-arts--visual-arts--sculpture-3d-art:fine-arts--visual-arts--sculpture-3d-art--15',1,'{"question":"How can texture affect a three-dimensional work?","choices":["It changes the sculpture''s dimensions","It removes the form","It changes how surfaces look and may invite tactile interpretation","It sets its historical era"],"answer":2,"explanation":""}'::jsonb,'cb4728f269be7738928a3cdb5f775a9c','official',NULL,NULL,'Sculpture & 3D Art'),
