('original:fine-arts--visual-arts--digital-illustration:fine-arts--visual-arts--digital-illustration--20',1,'{"question":"Why inspect an illustration at several zoom levels?","choices":["Zoom changes the original subject","It ensures every image prints perfectly","It replaces feedback","Different scales reveal composition and detail problems"],"answer":3,"explanation":""}'::jsonb,'bc4b9784e1df2ae19ab001c7b80f1985','official',NULL,NULL,'Digital Illustration'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--1',1,'{"question":"What is the first step in a common art critique process?","choices":["Describe what is visibly present without judging it","Assign a grade immediately","Guess the artist''s private intention","Compare it to every artwork"],"answer":0,"explanation":""}'::jsonb,'3c7d528e608c27e104ea0b12dcfb9c92','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--2',1,'{"question":"What does analysis ask a viewer to examine?","choices":["The artwork''s retail price","How elements and principles are organized","The artist''s personality","The viewer''s favorite color only"],"answer":1,"explanation":""}'::jsonb,'1494de39d0dd5cf09e2c123f24ff3aea','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--3',1,'{"question":"What is interpretation in art critique?","choices":["A list of objects only","A guess with no evidence","A reasoned idea about meaning supported by visual evidence","A final score"],"answer":2,"explanation":""}'::jsonb,'9c419bea01474f944587f750ac875a64','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--4',1,'{"question":"What does evaluation involve?","choices":["Naming every color","Describing the frame only","Identifying the artist''s age","Judging effectiveness using reasons or criteria"],"answer":3,"explanation":""}'::jsonb,'1f3a221aac66c2fe710e3910a8e51314','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--5',1,'{"question":"Why should a critique distinguish observation from interpretation?","choices":["It helps separate visible evidence from possible meaning","Interpretations are always incorrect","Observation eliminates all meaning","The two steps are identical"],"answer":0,"explanation":""}'::jsonb,'5ca4f6051dbb31a2db35780c3517f928','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--6',1,'{"question":"Which comment is most constructive?","choices":["This is bad","The focal point is clear because contrast draws attention to the central figure","I like it, so nothing should change","You should copy another artist"],"answer":1,"explanation":""}'::jsonb,'759a2a86a10c17485ae044e1258a1da5','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--7',1,'{"question":"What is one purpose of an artist statement?","choices":["Replace the artwork","Prove every viewer must agree","Explain choices, process, or ideas behind a work","List only the materials'' prices"],"answer":2,"explanation":""}'::jsonb,'c9c9a5ce5c30d4818b223325c2073ca8','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--8',1,'{"question":"What is ideation in the creative process?","choices":["Applying a final protective coat","Displaying the finished piece","Writing a review after viewing","Generating and exploring possible ideas"],"answer":3,"explanation":""}'::jsonb,'0a829fe29efc8364a0ad049961898af2','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--9',1,'{"question":"Why make multiple thumbnails before a final composition?","choices":["They let the artist compare layouts quickly","They guarantee every layout is finished","They remove the need for revision","They select the artwork''s meaning"],"answer":0,"explanation":""}'::jsonb,'ffb4c4256532e9c3ab42415457a76565','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--10',1,'{"question":"What is a prototype or study useful for?","choices":["Making a final gallery label","Testing materials or visual ideas on a smaller scale","Avoiding experimentation","Proving the first idea is best"],"answer":1,"explanation":""}'::jsonb,'eb3ca707f0e09c13f61a863f0834ffd5','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--11',1,'{"question":"How can an artist use feedback productively?","choices":["Make every suggested change automatically","Reject all comments","Consider specific observations and decide which revisions serve the goal","Let feedback replace artistic intent"],"answer":2,"explanation":""}'::jsonb,'c882814c213585e688bcae4876f4f4bc','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--12',1,'{"question":"Why keep process documentation?","choices":["It guarantees a successful outcome","It removes uncertainty","It replaces the final work","It records decisions, experiments, and changes over time"],"answer":3,"explanation":""}'::jsonb,'ad8ff319f1282a467000500e6cfa979e','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--13',1,'{"question":"A viewer interprets an artwork differently from its creator. What can a thoughtful critique do?","choices":["Discuss evidence and context while recognizing multiple interpretations","Declare only the creator''s reading valid","Ignore the artwork''s visual details","End discussion immediately"],"answer":0,"explanation":""}'::jsonb,'1f4069d2c4bda28644bf79fa18c446a4','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--14',1,'{"question":"What is revision in the creative process?","choices":["Repeating the same step without reflection","Reconsidering and changing work to strengthen its purpose","Selecting a frame","Displaying a work publicly"],"answer":1,"explanation":""}'::jsonb,'4c64a7aedcd2dd3c5809464002b8f42d','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--15',1,'{"question":"How can criteria improve a critique?","choices":["They guarantee identical opinions","They remove all interpretation","They make judgments clearer and connected to the assignment''s goals","They apply only to realistic art"],"answer":2,"explanation":""}'::jsonb,'ef90c05b0c82d9dff92f5b485cdfb0c8','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--16',1,'{"question":"Which statement uses visual evidence?","choices":["The artist was probably angry","The work is definitely about a storm","It is the best painting in the room","Repeated diagonal lines lead the eye toward the bright doorway"],"answer":3,"explanation":""}'::jsonb,'d53cbc9b533ac0183ccd3510f8a54f74','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--17',1,'{"question":"Why might an artist revisit an initial goal during production?","choices":["The work may shift, and the artist can decide whether that change is productive","The initial goal must never change","Revision is always a mistake","Goals determine the final grade automatically"],"answer":0,"explanation":""}'::jsonb,'6b36e55174cee4511d2f012256307b59','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--18',1,'{"question":"What does reflection contribute after completing a project?","choices":["It proves the work is perfect","It helps the artist identify learning and future questions","It replaces critique","It guarantees the next project"],"answer":1,"explanation":""}'::jsonb,'40f86b96f51735199db0ca14a93eaf04','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--19',1,'{"question":"How can a critique be respectful and rigorous?","choices":["Avoid specific comments","Praise every decision without thought","Address choices and evidence rather than attacking the artist","Judge the artist''s character"],"answer":2,"explanation":""}'::jsonb,'0272622499a57915b7d221ce6c1973c3','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--visual-arts--art-critique-creative-process:fine-arts--visual-arts--art-critique-creative-process--20',1,'{"question":"A student says an artwork is unsuccessful. What follow-up encourages analysis?","choices":["Ask who made it","End the discussion","Tell them all artworks are equally effective","Ask which goal or criterion is not being met and point to evidence"],"answer":3,"explanation":""}'::jsonb,'51f0b0946078706353b520f06ce007dd','official',NULL,NULL,'Art Critique & Creative Process'),
('original:fine-arts--media-arts--storyboarding-visual-storytelling:fine-arts--media-arts--storyboarding-visual-storytelling--1',1,'{"question":"What is a storyboard?","choices":["A sequence of sketches planning shots or scenes","A finished soundtrack","A list of camera prices","A collection of unrelated images"],"answer":0,"explanation":""}'::jsonb,'72ec426c532158807171fc852400139b','official',NULL,NULL,'Storyboarding & Visual Storytelling'),
