('original:fine-arts--media-arts--storyboarding-visual-storytelling:fine-arts--media-arts--storyboarding-visual-storytelling--3',1,'{"question":"What does a shot list record?","choices":["Only the story''s dialogue","The actors'' private notes","Planned shots and production details","The editing software version"],"answer":2,"explanation":""}'::jsonb,'cc59eb9876147b42cf82ae40b13c358c','official',NULL,NULL,'Storyboarding & Visual Storytelling'),
('original:fine-arts--media-arts--storyboarding-visual-storytelling:fine-arts--media-arts--storyboarding-visual-storytelling--4',1,'{"question":"What information can arrows in a storyboard communicate?","choices":["The image''s color profile","Copyright ownership","The frame rate","Movement of a subject or camera"],"answer":3,"explanation":""}'::jsonb,'3e9d783d43742470bea90267b80c6c12','official',NULL,NULL,'Storyboarding & Visual Storytelling'),
