('original:fine-arts--media-arts--storyboarding-visual-storytelling:fine-arts--media-arts--storyboarding-visual-storytelling--6',1,'{"question":"How can a close-up support storytelling?","choices":["It always shows the full setting","It emphasizes a detail, expression, or reaction","It removes emotional meaning","It sets the scene''s total duration"],"answer":1,"explanation":""}'::jsonb,'4f4ec4d6350e7f2403e71c21d277b725','official',NULL,NULL,'Storyboarding & Visual Storytelling'),
('original:fine-arts--media-arts--storyboarding-visual-storytelling:fine-arts--media-arts--storyboarding-visual-storytelling--7',1,'{"question":"What is a point-of-view shot?","choices":["A shot of the camera operator","A view from the audience only","A view framed as if seen by a character","A shot without perspective"],"answer":2,"explanation":""}'::jsonb,'3ada577bf20973be9ac5634436548fde','official',NULL,NULL,'Storyboarding & Visual Storytelling'),
